const safeRead=(key,fallback)=>{try{const value=localStorage.getItem(key);return value===null?fallback:JSON.parse(value)}catch{return fallback}};
const safeWrite=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value));return true}catch{return false}};
const body=document.body,root=document.documentElement;
let storageAvailable=true;
const savedTheme=(()=>{try{return localStorage.getItem('pypink-theme')}catch{storageAvailable=false;return null}})();
const preferred=matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light';
let theme=savedTheme||root.dataset.theme||preferred;
function setTheme(next,persist=true){theme=next;root.dataset.theme=next;body.dataset.theme=next;body.classList.toggle('dark',next==='dark');const button=document.querySelector('[data-theme-toggle]');if(button){button.innerHTML=`<i class="fa-solid ${next==='dark'?'fa-sun':'fa-moon'}"></i><span>${next==='dark'?'Mode Siang':'Mode Malam'}</span>`;button.setAttribute('aria-label',next==='dark'?'Aktifkan mode siang':'Aktifkan mode malam')}if(persist){try{localStorage.setItem('pypink-theme',next)}catch{storageAvailable=false}}}
setTheme(theme,false);
document.querySelector('[data-theme-toggle]')?.addEventListener('click',()=>setTheme(theme==='dark'?'light':'dark'));
const toast=document.querySelector('.toast');let toastTimer;
window.pypinkToast=(message='Pipi bilang: kamu hebat!')=>{if(!toast)return;toast.querySelector('[data-toast-message]').textContent=message;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),2800)};
document.querySelectorAll('[data-menu-toggle]').forEach(button=>button.addEventListener('click',()=>{const drawer=document.querySelector('.drawer');drawer?.classList.toggle('open');button.setAttribute('aria-expanded',drawer?.classList.contains('open')?'true':'false')}));
document.querySelector('[data-back-top]')?.addEventListener('click',()=>window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}));
let progress=safeRead('pypink-progress',{});if(!progress||typeof progress!=='object'||Array.isArray(progress))progress={};
function renderProgress(){document.querySelectorAll('[data-lesson-slug]').forEach(card=>{const label=card.querySelector('[data-status]');if(label)label.textContent=progress[card.dataset.lessonSlug]?'✓ Selesai':'Belum mulai'});const total=Number(document.querySelector('[data-progress-total]')?.dataset.progressTotal)||30;const done=Object.keys(progress).filter(key=>progress[key]).length;const levelCounts=safeRead('pypink-level-progress',{});document.querySelectorAll('[data-global-progress]').forEach(el=>{el.textContent=`${Math.min(100,Math.round(done/total*100))}%`});document.querySelectorAll('[data-progress-bar]').forEach((bar,index)=>{const level=bar.dataset.level||String(index+1);const cards=[...document.querySelectorAll('[data-lesson-slug]')].filter(card=>card.dataset.level===level);const count=Number(bar.dataset.total)||cards.length||total;const completed=level==='all'?done:cards.length?cards.filter(card=>progress[card.dataset.lessonSlug]).length:Number(levelCounts[level]||0);bar.style.width=`${Math.min(100,completed/count*100)}%`})}
renderProgress();
document.querySelectorAll('[data-filter-level], [data-search-lessons]').forEach(el=>el.addEventListener(el.tagName==='INPUT'?'input':'change',()=>{const level=document.querySelector('[data-filter-level]')?.value||'all';const query=(document.querySelector('[data-search-lessons]')?.value||'').toLowerCase();document.querySelectorAll('[data-lesson-slug]').forEach(card=>{card.hidden=(level!=='all'&&card.dataset.level!==level)||!card.textContent.toLowerCase().includes(query)});document.querySelectorAll('.level-section').forEach(section=>section.hidden=!section.querySelector('[data-lesson-slug]:not([hidden])'))}));
document.querySelectorAll('[data-copy]').forEach(button=>button.addEventListener('click',async()=>{const code=button.closest('.code-frame')?.querySelector('code')?.innerText||button.parentElement.querySelector('pre')?.innerText||'';try{await navigator.clipboard.writeText(code);window.pypinkToast('Kode tersalin! Pipi ikut bangga 🐍')}catch{window.pypinkToast('Salin kode gagal. Pilih kode lalu tekan Ctrl+C, ya!')}}));
document.querySelectorAll('[data-try-code]').forEach(link=>link.addEventListener('click',()=>{try{sessionStorage.setItem('pypink-playground-code',link.dataset.tryCode)}catch{}}));
let quizCorrect=0,quizAnswered=0;document.querySelectorAll('[data-quiz]').forEach(quiz=>quiz.querySelectorAll('[data-answer]').forEach(option=>option.addEventListener('click',()=>{if(option.disabled)return;quiz.querySelectorAll('[data-answer]').forEach(item=>item.disabled=true);const correct=option.dataset.answer==='true';quizAnswered+=1;if(correct)quizCorrect+=1;option.classList.add(correct?'correct':'wrong');quiz.querySelector('.quiz-feedback').textContent=correct?'Betul! Pipi kasih bintang buat kamu ⭐':`Belum tepat. ${quiz.dataset.explanation||'Coba baca konsepnya lagi, ya!'}`;document.querySelectorAll('[data-quiz-score]').forEach(score=>score.textContent=`${quizCorrect} / ${quizAnswered}`);const total=document.querySelectorAll('[data-quiz]').length;document.querySelectorAll('[data-score-message]').forEach(message=>message.textContent=quizAnswered===total?'Selesai! Pipi bangga sama usaha kamu 🐍':correct?'Jawaban tepat, satu bintang buat kamu!':'Gapapa, salah itu bagian dari belajar.');}))); 
document.querySelector('[data-mark-complete]')?.addEventListener('click',()=>{const id=document.querySelector('[data-lesson-id]')?.dataset.lessonId;if(!id)return;const level=document.querySelector('[data-lesson-level]')?.dataset.lessonLevel||'1';const levelCounts=safeRead('pypink-level-progress',{});if(!progress[id])levelCounts[level]=(Number(levelCounts[level])||0)+1;progress[id]=true;const stored=safeWrite('pypink-progress',progress)&&safeWrite('pypink-level-progress',levelCounts);renderProgress();document.querySelector('[data-mark-complete]').textContent='✓ Materi selesai';window.pypinkToast(stored?'Materi selesai! Kamu keren banget ✨':'Selesai untuk sesi ini. Storage browser sedang tidak tersedia, ya!')});
document.querySelectorAll('[data-heart]').forEach(button=>button.addEventListener('click',event=>{if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const star=document.createElement('span');star.textContent='✦';star.setAttribute('aria-hidden','true');star.style.cssText=`position:fixed;left:${event.clientX}px;top:${event.clientY}px;color:#ff5c9a;font-size:25px;pointer-events:none;z-index:80;transition:all .6s`;document.body.append(star);requestAnimationFrame(()=>{star.style.transform='translateY(-35px) scale(.2)';star.style.opacity='0'});setTimeout(()=>star.remove(),700)}));
document.querySelector('[data-toc-toggle]')?.addEventListener('click',()=>document.querySelector('.toc')?.classList.toggle('open'));
document.querySelectorAll('[data-cheatsheet-search]').forEach(input=>input.addEventListener('input',()=>{const query=input.value.toLowerCase();document.querySelectorAll('[data-cheat-card]').forEach(card=>card.hidden=!card.textContent.toLowerCase().includes(query))}));
function updateStreak(){const today=new Date().toLocaleDateString('en-CA');const state=safeRead('pypink-streak',{lastDay:'',count:0});if(state.lastDay!==today){const yesterday=new Date(Date.now()-86400000).toLocaleDateString('en-CA');state.count=state.lastDay===yesterday?state.count+1:1;state.lastDay=today;safeWrite('pypink-streak',state)}document.querySelectorAll('[data-streak]').forEach(el=>{el.textContent=`🔥 ${state.count} hari`;el.title=`Kamu sudah belajar ${state.count} hari${state.count===1?'':' berturut-turut'}!`})}
updateStreak();
if(!savedTheme){matchMedia('(prefers-color-scheme: dark)').addEventListener?.('change',event=>{if(!(()=>{try{return localStorage.getItem('pypink-theme')}catch{return 'set'}})())setTheme(event.matches?'dark':'light',false)})}
